function startersFor(needs) {
  const out = new Set(['spring-boot-starter']);
  if (needs.chat) out.add('model-starter (e.g. openai)');
  if (needs.rag) out.add('vector-store-starter (e.g. pgvector)');
  if (needs.eval) out.add('testcontainers');
  if (needs.obs) out.add('micrometer-observation');
  if (needs.mcp) out.add('mcp-server-boot-starter');
  return [...out];
}
console.log(startersFor({ chat: true }).join(','));
console.log(startersFor({ chat: true, rag: true, eval: true, obs: true }).join(','));
console.log('minimal for chat-only: ' + startersFor({ chat: true }).length + ' starters');

